import os
import pandas as pd
import numpy as np
from datetime import datetime
from sklearn.linear_model import LinearRegression

# ==============================================================================
# FONCTIONS GLOBALES (Invisibles pour l'IA, utilisées par la classe Tools)
# ==============================================================================

FILE_PATH = r"C:\Users\gabri\Downloads\situations-budgetaires-transpose.csv"


def normalize_string(s: str) -> str:
    """Nettoyage simple de texte."""
    if s is None:
        return ""
    s = str(s).replace("\ufeff", "").strip().lower()
    return " ".join(s.split())


def load_budget_data():
    """Charge le CSV de manière robuste."""
    if not os.path.exists(FILE_PATH):
        return None, f"Erreur critique : Fichier introuvable au chemin {FILE_PATH}"

    encodings = ["utf-8", "utf-8-sig", "latin1", "cp1252"]
    seps = [";", ","]

    last_err = None
    # 1. Lecture brute
    for enc in encodings:
        for sep in seps:
            try:
                df = pd.read_csv(FILE_PATH, sep=sep, encoding=enc, engine="python")
                if df.shape[1] < 2:
                    continue  # Mauvais séparateur
                df.columns = [normalize_string(c) for c in df.columns]

                # 2. Détection Date
                date_col = None
                if "date" in df.columns:
                    date_col = "date"
                else:
                    # Recherche heuristique
                    for c in df.columns:
                        try:
                            sample = df[c].astype(str).head(10).tolist()
                            if sum(1 for v in sample if "/" in v or "-" in v) >= 8:
                                date_col = c
                                break
                        except:
                            continue

                if not date_col:
                    return None, {
                        "error": "DATE_MISSING",
                        "available_columns": list(df.columns),
                    }

                if date_col != "date":
                    df = df.rename(columns={date_col: "date"})

                # 3. Parsing Date
                df["date"] = pd.to_datetime(df["date"], dayfirst=True, errors="coerce")
                if df["date"].isna().all():
                    df["date"] = pd.to_datetime(df["date"], errors="coerce")

                df = (
                    df.dropna(subset=["date"])
                    .sort_values("date")
                    .reset_index(drop=True)
                )
                if df.empty:
                    return None, "Fichier vide après nettoyage."

                return df, None

            except Exception as e:
                last_err = str(e)

    return None, f"Erreur lecture CSV : {last_err}"


def find_column_smart(df, user_query):
    """Cherche une colonne (avec dictionnaire de synonymes pour TVA, IS, etc.)."""
    if isinstance(df, dict) or df is None:
        return None

    # Normalisation locale pour être sûr
    query = str(user_query).replace("\ufeff", "").strip().lower()

    # --- 1. Dictionnaire de Synonymes (La solution infaillible) ---
    # Cela permet de trouver "TVA" même si le fichier dit "Taxe sur la valeur ajoutée"
    aliases = {
        "tva": "taxe sur la valeur ajoutée",
        "is": "impôt sur les sociétés",
        "ir": "impôt sur le revenu",
        "ticpe": "taxe intérieure de consommation",
        "dette": "charges de la dette",
        "recettes": "total recettes nettes",
        "dépenses": "total dépenses nettes",
        "solde": "solde budgétaire",
        "deficit": "solde budgétaire",
    }

    # On regarde si un mot de la requête est un alias connu
    # Exemple : "Analyse la TVA" -> tokens contient "tva" -> on cherche "taxe sur la valeur ajoutée"
    tokens = query.split()
    for alias, target in aliases.items():
        if alias == query or alias in tokens:
            # On cherche la cible dans les colonnes du CSV
            matches = [c for c in df.columns if target in c]
            if matches:
                return matches[0]
    # --------------------------------------------------------------

    # 2. Correspondance Exacte
    if query in df.columns:
        return query

    # 3. Correspondance Partielle (Classique)
    matches = [c for c in df.columns if query in c and c != "date"]
    return matches[0] if matches else None


def calc_monthly_flow(df, col_name):
    """Transforme Stock -> Flux."""
    temp = df.copy()
    temp["year"] = temp["date"].dt.year
    temp[col_name] = pd.to_numeric(temp[col_name], errors="coerce")
    temp["flow"] = temp.groupby("year")[col_name].diff()
    temp["flow"] = temp["flow"].fillna(temp[col_name])
    return temp["flow"]


def error_col_not_found(df, name):
    return {
        "error": f"Métrique '{name}' introuvable.",
        "instruction_for_model": "Analyse la liste 'available_columns', trouve le bon nom, et relance l'outil.",
        "available_columns": [c for c in df.columns if c != "date"],
    }


# ==============================================================================
# CLASSE TOOLS (Seules ces fonctions seront vues par l'IA)
# ==============================================================================


class Tools:
    def __init__(self):
        pass  # Plus besoin de config ici, tout est en global

    def budget_list_metrics(self) -> dict:
        df, error = load_budget_data()
        if error:
            return {"error": error}
        metrics = [c for c in df.columns if c != "date"]
        return {"count": len(metrics), "metrics": metrics}

    def analyze_budget_metric(self, metric_name: str) -> dict:
        df, error = load_budget_data()
        if error:
            return {"error": error}

        col = find_column_smart(df, metric_name)
        if not col:
            return error_col_not_found(df, metric_name)

        series = pd.to_numeric(df[col], errors="coerce").dropna()
        if len(series) < 2:
            return {"error": "Pas assez de données."}

        last_val = float(series.iloc[-1])
        prev_val = float(series.iloc[-2])
        variation = (
            ((last_val - prev_val) / abs(prev_val)) * 100 if prev_val != 0 else 0
        )

        return {
            "type": "Descriptive Stats",
            "metric": col,
            "latest_value": last_val,
            "variation_percent": round(variation, 2),
            "mean": round(float(series.mean()), 2),
        }

    def decompose_time_series(self, metric_name: str) -> dict:
        df, error = load_budget_data()
        if error:
            return {"error": error}
        col = find_column_smart(df, metric_name)
        if not col:
            return error_col_not_found(df, metric_name)

        try:
            series_flow = calc_monthly_flow(df, col)
        except:
            return {"error": "Erreur calcul flux."}

        series_flow.index = df["date"]
        series_flow = series_flow.dropna()
        if len(series_flow) < 24:
            return {"error": "Données insuffisantes (min 2 ans)."}

        trend = series_flow.rolling(window=12, center=True).mean()
        detrended = series_flow - trend
        seasonality = detrended.groupby(detrended.index.month).mean()

        recent = trend.dropna().iloc[-12:]
        trend_dir = (
            "Hausse"
            if not recent.empty and float(recent.iloc[-1]) > float(recent.iloc[0])
            else "Baisse"
        )

        return {
            "type": "Decomposition",
            "metric": col,
            "trend": trend_dir,
            "seasonality": {m: round(float(v), 2) for m, v in seasonality.items()},
        }


def plot_ascii_trend(self, metric_name: str) -> dict:
    df, error = load_budget_data()
    if error:
        return {"error": error}
    col = find_column_smart(df, metric_name)
    if not col:
        return error_col_not_found(df, metric_name)

    # 1. Conversion en FLUX MENSUEL (Indispensable pour la cohérence)
    try:
        # On utilise la fonction globale définie plus haut
        series = calc_monthly_flow(df, col)
    except:
        series = pd.to_numeric(df[col], errors="coerce")

    # On prend les 24 derniers mois
    # Attention : series est indexé par le DataFrame original, il faut recréer un DF propre
    data = pd.DataFrame({"date": df["date"], "value": series})
    data = data.dropna().tail(24)

    if data.empty:
        return {"error": "Données vides."}

    vals = data["value"].values
    dates = data["date"].tolist()
    min_v, max_v = vals.min(), vals.max()
    rng = max_v - min_v if max_v != min_v else 1

    # 2. Gestion automatique de l'unité (Mds ou M)
    abs_max = max(abs(min_v), abs(max_v))
    if abs_max >= 1e9:
        scale_label = "Mds €"
        divider = 1e9
    elif abs_max >= 1e6:
        scale_label = "M €"
        divider = 1e6
    else:
        scale_label = "€"
        divider = 1

    chart = []
    chart.append(f"--- Évolution Mensuelle : {col} (en {scale_label}) ---")

    for i, (d, v) in enumerate(zip(dates, vals)):
        # Barres ASCII
        height = int(((v - min_v) / rng) * 10)
        bar = "█" * max(height, 1)

        # 3. Calcul de la tendance (Icône)
        icon = ""
        if i > 0:
            prev = vals[i - 1]
            if v > prev:
                icon = "↗"
            elif v < prev:
                icon = "↘"
            else:
                icon = "→"

        # Formatage final
        val_fmt = f"{v/divider:+.1f}"
        chart.append(f"{d.strftime('%Y-%m')} | {bar} ({val_fmt} {icon})")

    return {"type": "ASCII Chart", "metric": col, "plot": "\n".join(chart)}


def predict_budget_trend(self, metric_name: str, months_ahead: int = 6) -> dict:
    df, error = load_budget_data()
    if error:
        return {"error": error}
    col = find_column_smart(df, metric_name)
    if not col:
        return error_col_not_found(df, metric_name)

    data = df[["date", col]].copy()
    data[col] = pd.to_numeric(data[col], errors="coerce")
    data = data.dropna()
    if len(data) < 6:
        return {"error": "Pas assez de données."}

    data["ordinal"] = data["date"].map(datetime.toordinal)
    X = data[["ordinal"]].values
    y = data[col].values

    model = LinearRegression()
    model.fit(X, y)
    r2 = model.score(X, y)

    last_date = data["date"].max()
    future_dates = [
        last_date + pd.DateOffset(months=i) for i in range(1, int(months_ahead) + 1)
    ]
    preds = model.predict(
        np.array([d.toordinal() for d in future_dates]).reshape(-1, 1)
    )

    return {
        "type": "Prediction",
        "metric": col,
        "r2_score": round(r2, 4),
        "forecast": [
            {"date": d.strftime("%Y-%m-%d"), "value": round(float(v), 2)}
            for d, v in zip(future_dates, preds)
        ],
    }


def detect_anomalies(self, metric_name: str) -> dict:
    df, error = load_budget_data()
    if error:
        return {"error": error}
    col = find_column_smart(df, metric_name)
    if not col:
        return error_col_not_found(df, metric_name)

    try:
        series = calc_monthly_flow(df, col)
    except:
        series = pd.to_numeric(df[col], errors="coerce")

    series = series.dropna()
    if len(series) < 10:
        return {"error": "Pas assez de données."}

    mean, std = series.mean(), series.std()
    threshold = 2 * std if std > 0 else 0

    anomalies = []
    for idx, val in series.items():
        if std > 0 and abs(val - mean) > threshold:
            anomalies.append(
                {
                    "date": df.loc[idx, "date"].strftime("%Y-%m-%d"),
                    "value": round(float(val), 2),
                    "type": "Haut" if val > mean else "Bas",
                }
            )

    return {
        "type": "Anomalies",
        "metric": col,
        "count": len(anomalies),
        "list": anomalies[-10:],
    }


def compare_metrics_correlation(self, metric_a: str, metric_b: str) -> dict:
    df, error = load_budget_data()
    if error:
        return {"error": error}
    c1 = find_column_smart(df, metric_a)
    c2 = find_column_smart(df, metric_b)

    missing = []
    if not c1:
        missing.append(metric_a)
    if not c2:
        missing.append(metric_b)

    if missing:
        return {
            "error": f"Métriques introuvables : {', '.join(missing)}",
            "instruction_for_model": "Choisis les bons noms dans available_columns et relance.",
            "available_columns": [c for c in df.columns if c != "date"],
        }

    data = df[[c1, c2]].apply(pd.to_numeric, errors="coerce").dropna()
    if len(data) < 10:
        return {"error": "Données insuffisantes."}

    corr = data[c1].corr(data[c2])
    return {"metric_a": c1, "metric_b": c2, "correlation": round(float(corr), 3)}


def budget_query(
    self,
    aggregate: str,
    since_year: int = None,
    until_year: int = None,
    last_n_months: int = None,
    mode: str = "ytd",
    operation: str = "stats",
    manual_date_col: str = None,
) -> dict:
    """
    Outil principal d'analyse (Query).
    """
    # Note: Si manual_date_col est passé, on pourrait modifier load_budget_data
    # mais ici load_budget_data est global.
    # Pour simplifier dans cette architecture stricte :
    # L'auto-détection est suffisamment puissante maintenant.
    df, error = load_budget_data()

    if error:
        if isinstance(error, dict) and error.get("error") == "DATE_MISSING":
            # Cas extrême : on renvoie l'erreur pour que l'humain aide,
            # mais l'IA ne pourra pas corriger le code global dynamiquement.
            # C'est une limitation de sécurité acceptable.
            return error
        return {"error": error}

    col = find_column_smart(df, aggregate)
    if not col:
        return error_col_not_found(df, aggregate)

    work = df[["date", col]].copy()

    if str(mode).lower() == "flow":
        flow_series = calc_monthly_flow(df, col)
        work["value"] = flow_series
    else:
        work["value"] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=["value"])

    if since_year is not None:
        work = work[work["date"].dt.year >= int(since_year)]
    if until_year is not None:
        work = work[work["date"].dt.year <= int(until_year)]
    if last_n_months is not None:
        work = work.sort_values("date").tail(int(last_n_months))

    if work.empty:
        return {"error": "Aucune donnée après filtrage."}

    vals = work["value"].values
    op = str(operation).lower()

    if op == "sum":
        return {"result": float(np.sum(vals))}
    if op == "mean":
        return {"result": float(np.mean(vals))}
    if op == "max":
        idx = np.argmax(vals)
        return {
            "max_value": float(vals[idx]),
            "date": work.iloc[idx]["date"].strftime("%Y-%m-%d"),
        }

    return {
        "metric": col,
        "count": len(vals),
        "sum": float(np.sum(vals)),
        "mean": round(float(np.mean(vals)), 2),
        "min": float(np.min(vals)),
        "max": float(np.max(vals)),
    }
